import { ReactionPicker, Card } from "march/ui"

// günün havası: kendi emojilerin, seçilen büyük yazılır
export function MoodMeter() {
  let $mood = ""
  return <Card m:theme="night">
    <ReactionPicker emojis={["☀️", "⛅", "🌧️", "⛈️", "❄️"]} selected={$mood} onPick={(e: string) => $mood = e} m:color="brand-orange" label="Hava" />
    <span sx={{ text: "2xl" }}>{$mood || "?"}</span>
  </Card>
}

import { ReactionPicker } from "march/ui"

// mesaja tepki: aynı emojiye yeniden basınca kalkar; + düğmesi tam paneli açar
export function MessageReactions() {
  let $sel = ""
  let $panel = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <p>“Yarın 7'de sahilde!”</p>
    <ReactionPicker selected={$sel} onPick={(e: string) => $sel = $sel === e ? "" : e} onMore={() => $panel = !$panel} />
    {() => ($panel ? <ReactionPicker layout="grid" onPick={(e: string) => { $sel = e; $panel = false }} /> : null)}
  </div>
}

import { ReactionPicker } from "march/ui"
import { smile } from "march/icons"

// ReactionPicker'ın özellikleri: onPick, emojis, selected, layout, onMore, pop, label, emojiLabel, moreLabel, moreIcon, class
export function ReactionPickerLab() {
  let $sel = "👍"
  let $more = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <ReactionPicker class="lab-row" emojis={["👍", "🎉", "🔥"]} selected={$sel} onPick={(e: string) => $sel = e} pop={false}
      label="Tepkiler" emojiLabel={(e: string) => `Tepki ${e}`} onMore={() => $more++} moreLabel="Daha çok" moreIcon={smile} />
    <span class="lab-sel">{$sel} · {$more}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ReactionPickerLab } from "./ReactionPickerLab.tsx"

// ReactionPickerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("seçili tepki aria-pressed, basınca onPick", async () => {
  const s = renderTest(() => <ReactionPickerLab />)
  expect(s.find("Tepki 👍")?.getAttribute("aria-pressed")).toBe("true")
  await s.click("Tepki 🔥")
  expect(s.get(".lab-sel")?.textContent).toContain("🔥")
})

test("+ düğmesi moreLabel adıyla onMore'u çağırır", async () => {
  const s = renderTest(() => <ReactionPickerLab />)
  await s.click("Daha çok")
  expect(s.get(".lab-sel")?.textContent).toContain("1")
})
